{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "data": {
    "values": [
      {"category": "David Justice", "value": 104, "year": 1995, "tag": "hit"},
      {"category": "Derek Jeter", "value": 12, "year": 1995, "tag": "hit"},
      {"category": "David Justice", "value": 45, "year": 1996, "tag": "hit"},
      {"category": "Derek Jeter", "value": 183, "year": 1996, "tag": "hit"},
      {"category": "David Justice", "value": 307, "year": 1995, "tag": "miss"},
      {"category": "Derek Jeter", "value": 36, "year": 1995, "tag": "miss"},
      {"category": "David Justice", "value": 95, "year": 1996, "tag": "miss"},
      {"category": "Derek Jeter", "value": 399, "year": 1996, "tag": "miss"}
    ]
  },
  "title": "Proportion of Hit/Miss by Player and Year",
  "facet": {
    "row": {"field": "category", "type": "nominal"},
    "column": {"field": "year", "type": "nominal"}
  },
  "spec": {
    "layer": [
      {
        "transform": [
          {
            "groupby": ["category", "year"],
            "ops": ["sum"],
            "fields": ["value"],
            "as": ["total_value"]
          },
          {
            "joinaggregate": [{
              "op": "sum",
              "field": "value",
              "as": "group_total"
            }],
            "groupby": ["category", "year"]
          },
          {
            "calculate": "datum.value / datum.group_total",
            "as": "proportion"
          },
          {
            "calculate": "format(datum.proportion, '0.00%')",
            "as": "formatted_proportion"
          }
        ],
        "encoding": {
          "theta": {"field": "value", "type": "quantitative"},
          "color": {"field": "tag", "type": "nominal", "legend": {"title": "Outcome"}},
          "tooltip": [
            {"field": "tag", "type": "nominal", "title": "Tag"},
            {"field": "value", "type": "quantitative"},
            {"field": "proportion", "type": "quantitative", "title": "Proportion"},
            {"field": "formatted_proportion", "type": "nominal", "title": "Proportion (formatted)"}
          ],
          "opacity": {"value": 1}
        },
        "mark": {"type": "arc"},
        "encoding2": {
          "theta": {"field": "value", "type": "quantitative"},
          "radius": {"value": 80}
        }
      },
      {
        "transform": [
          {"calculate": "datum.proportion * 100", "as": "proportion_percent"},
          {"calculate": "format(datum.proportion_percent, '.2f')", "as": "formatted_proportion"},
          {"calculate": "datum.formatted_proportion + '%' ", "as": "formatted_proportion_percent"}
        ],
        "mark": {
          "type": "text",
          "align": "center",
          "baseline": "middle",
          "radius": 80
        },
        "encoding": {
          "theta": {"field": "value", "type": "quantitative"},
          "text": {"field": "formatted_proportion", "type": "nominal"},
          "radius": {"value": 80},
          "tooltip": [
            {"field": "tag", "type": "nominal", "title": "Tag"},
            {"field": "value", "type": "quantitative"},
            {"field": "formatted_proportion", "type": "nominal", "title": "Proportion"}
          ]
        }
      }
    ]
  },
  "config": {
    "view": {"stroke": "transparent"},
    "title": {"anchor": "start", "fontSize": 14}
  }
}

